#!/usr/bin/env python3
"""
recall.py — search your memory across all tiers (and the cloud, if configured).

Searches the local memory/ folders (global, shared, project). If SUPABASE_URL and
SUPABASE_KEY are set (in the environment or .env), it also runs a keyword search
against the cloud mirror via the search_memories() function.

Usage:  python3 recall.py "<query>"
"""
from __future__ import annotations

import json
import os
import re
import sys
import urllib.request
from pathlib import Path

MAX_PER_TIER = 6
MAX_CLOUD = 6
TIERS = ["global", "shared", "project"]


def load_dotenv() -> None:
    here = Path.cwd()
    for d in [here, *here.parents]:
        env = d / ".env"
        if env.exists():
            for line in env.read_text(errors="ignore").splitlines():
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, _, v = line.partition("=")
                k, v = k.strip(), v.strip().strip('"').strip("'")
                if k and k not in os.environ:
                    os.environ[k] = v
            return


def find_memory_root() -> Path | None:
    """Walk up from cwd to find a 'memory' folder that has tier subdirs."""
    here = Path.cwd()
    for d in [here, *here.parents]:
        cand = d / "memory"
        if (cand / "global").exists() or (cand / "project").exists():
            return cand
    return None


def search_dir(directory: Path, query: str, label: str):
    if not directory.exists():
        return []
    q = query.lower()
    q_words = [w for w in re.findall(r"\w+", q) if len(w) >= 2]
    results = []
    for path in sorted(directory.rglob("*.md")):
        if path.name.startswith("_"):
            continue
        try:
            text = path.read_text(errors="ignore")
        except OSError:
            continue
        name_score = 5 if q in path.stem.lower() else (2 if any(w in path.stem.lower() for w in q_words) else 0)
        for i, line in enumerate(text.splitlines(), 1):
            ll = line.lower()
            if q in ll:
                results.append((10 + name_score, label, path.name, i, line.strip()))
            elif q_words and all(w in ll for w in q_words):
                results.append((6 + name_score, label, path.name, i, line.strip()))
            elif q_words and any(w in ll for w in q_words):
                results.append((2 + name_score, label, path.name, i, line.strip()))
    seen, unique = set(), []
    for r in sorted(results, key=lambda x: -x[0]):
        sig = (r[1], r[2], r[4][:80])
        if sig in seen:
            continue
        seen.add(sig)
        unique.append(r)
    return unique[:MAX_PER_TIER]


def search_cloud(query: str):
    """Keyword search via the search_memories() RPC. Silent no-op if not configured."""
    url = (os.environ.get("SUPABASE_URL") or "").rstrip("/")
    key = os.environ.get("SUPABASE_KEY") or ""
    if not url or not key:
        return []
    body = json.dumps({"query_text": query, "match_count": MAX_CLOUD}).encode()
    req = urllib.request.Request(
        f"{url}/rest/v1/rpc/search_memories",
        data=body,
        headers={"apikey": key, "Authorization": f"Bearer {key}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=8) as r:
            rows = json.loads(r.read().decode())
    except Exception:
        return []
    out = []
    for row in rows if isinstance(rows, list) else []:
        content = (row.get("content") or "").strip()
        snippet = ""
        in_fm = False
        for line in content.splitlines():
            s = line.strip()
            if s == "---":
                in_fm = not in_fm
                continue
            if in_fm or not s or s.startswith("#"):
                continue
            snippet = s
            break
        out.append((row.get("client_id", "?"), row.get("file_path", "?"), snippet[:160]))
    return out


def main():
    load_dotenv()
    query = " ".join(a for a in sys.argv[1:] if a).strip()
    if not query:
        print('usage: python3 recall.py "<query>"', file=sys.stderr)
        return 2

    root = find_memory_root()
    tier_hits = {}
    if root:
        for tier in TIERS:
            tier_hits[tier] = search_dir(root / tier, query, tier)

    cloud_hits = search_cloud(query)

    if not (any(tier_hits.values()) or cloud_hits):
        print(f"No matches for: {query}")
        return 0

    for tier in TIERS:
        hits = tier_hits.get(tier) or []
        if hits:
            print(f"## {tier} ({len(hits)})")
            for _s, _l, fn, ln, content in hits:
                print(f"  memory/{tier}/{fn}:{ln} — {content[:140]}")
            print()

    if cloud_hits:
        print(f"## cloud (keyword) ({len(cloud_hits)})")
        for cid, fp, snippet in cloud_hits:
            print(f"  [{cid}] {fp}")
            if snippet:
                print(f"      {snippet}")

    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
n8n_execs.py — query your n8n executions/workflows via the REST API. MCP-free.

Reads your n8n host + API key from environment variables (or a .env file at the
repo root) and hits the n8n public REST API directly. Read-only: it inspects
runtime state, it never edits or triggers workflows.

Setup (once):
  1. Copy .env.example to .env at the repo root.
  2. Fill in N8N_API_URL and N8N_API_KEY.
     - URL is your instance base, e.g. https://yourname.app.n8n.cloud  (no /api/v1)
     - Key: n8n → Settings → n8n API → Create an API key.

Usage:
  n8n_execs.py recent [--days N] [--status error|success|running|...]
  n8n_execs.py exec <id> [--include-data]
  n8n_execs.py errors [--days N] [--limit N]
  n8n_execs.py wf <workflow_id> [--limit N]
  n8n_execs.py active                # currently-running executions
  n8n_execs.py health                # workflow + execution summary
  n8n_execs.py search <query>        # find workflows by name
  n8n_execs.py wf-info <workflow_id> # workflow metadata + trigger nodes
"""
from __future__ import annotations

import argparse
import json
import os
import sys
import time
import urllib.parse
import urllib.request
from collections import Counter
from datetime import datetime
from pathlib import Path


def load_dotenv() -> None:
    """Load KEY=VALUE pairs from the nearest .env file (walking up from cwd),
    without overwriting variables already set in the environment."""
    here = Path.cwd()
    for d in [here, *here.parents]:
        env = d / ".env"
        if env.exists():
            for line in env.read_text(errors="ignore").splitlines():
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, _, v = line.partition("=")
                k, v = k.strip(), v.strip().strip('"').strip("'")
                if k and k not in os.environ:
                    os.environ[k] = v
            return


def resolve_creds() -> tuple[str, str]:
    """Return (host_base_url, api_key) from N8N_API_URL / N8N_API_KEY."""
    load_dotenv()
    host = (os.environ.get("N8N_API_URL") or "").rstrip("/")
    key = os.environ.get("N8N_API_KEY") or ""
    if not host or not key:
        raise RuntimeError(
            "Missing n8n credentials. Set N8N_API_URL and N8N_API_KEY in your "
            "environment or in a .env file at the repo root (see .env.example)."
        )
    # Tolerate someone pasting the full /api/v1 URL.
    if host.endswith("/api/v1"):
        host = host[: -len("/api/v1")]
    return host, key


def http_get(url: str, key: str, timeout: int = 15) -> dict:
    req = urllib.request.Request(url, headers={"X-N8N-API-KEY": key})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        body = e.read().decode(errors="ignore")[:200]
        hint = ""
        if e.code in (401, 403):
            hint = " — check N8N_API_KEY (is it valid / not expired?)"
        elif e.code == 404:
            hint = " — check N8N_API_URL (base instance URL, no /api/v1)"
        raise RuntimeError(f"n8n HTTP {e.code}: {body}{hint}")
    except urllib.error.URLError as e:
        raise RuntimeError(f"Could not reach n8n at {url}: {e.reason}")


def workflow_name_map(host: str, key: str) -> dict:
    data = http_get(f"{host}/api/v1/workflows?limit=250", key)
    return {w["id"]: w.get("name", w["id"]) for w in data.get("data", [])}


def fmt_dur(started: str, stopped: str | None) -> float | None:
    try:
        t0 = datetime.fromisoformat(started.replace("Z", "+00:00"))
        if not stopped:
            return None
        t1 = datetime.fromisoformat(stopped.replace("Z", "+00:00"))
        return round((t1 - t0).total_seconds(), 2)
    except (ValueError, TypeError, AttributeError):
        return None


def cmd_recent(host, key, args):
    params = {"limit": args.limit, "includeData": "false"}
    if args.status:
        params["status"] = args.status
    url = f"{host}/api/v1/executions?" + urllib.parse.urlencode(params)
    data = http_get(url, key).get("data", [])
    names = workflow_name_map(host, key)
    cutoff = time.time() - args.days * 86400
    out = []
    for e in data:
        try:
            t = datetime.fromisoformat((e.get("startedAt") or "").replace("Z", "+00:00")).timestamp()
        except (ValueError, AttributeError):
            t = 0
        if t < cutoff:
            continue
        out.append({
            "id": e.get("id"),
            "started": e.get("startedAt"),
            "status": e.get("status"),
            "duration_s": fmt_dur(e.get("startedAt") or "", e.get("stoppedAt")),
            "workflow": names.get(e.get("workflowId"), e.get("workflowId")),
            "wf_id": e.get("workflowId"),
        })
    return out


def cmd_exec(host, key, args):
    inc = "true" if args.include_data else "false"
    return http_get(f"{host}/api/v1/executions/{args.id}?includeData={inc}", key)


def cmd_errors(host, key, args):
    params = {"limit": args.limit, "status": "error", "includeData": "false"}
    data = http_get(f"{host}/api/v1/executions?" + urllib.parse.urlencode(params), key).get("data", [])
    names = workflow_name_map(host, key)
    cutoff = time.time() - args.days * 86400
    out = []
    for e in data:
        try:
            t = datetime.fromisoformat((e.get("startedAt") or "").replace("Z", "+00:00")).timestamp()
        except (ValueError, AttributeError):
            continue
        if t < cutoff:
            continue
        out.append({
            "id": e.get("id"),
            "started": e.get("startedAt"),
            "workflow": names.get(e.get("workflowId"), e.get("workflowId")),
            "wf_id": e.get("workflowId"),
            "duration_s": fmt_dur(e.get("startedAt") or "", e.get("stoppedAt")),
        })
    return out


def cmd_wf(host, key, args):
    params = {"limit": args.limit, "workflowId": args.workflow_id, "includeData": "false"}
    data = http_get(f"{host}/api/v1/executions?" + urllib.parse.urlencode(params), key).get("data", [])
    return [
        {
            "id": e.get("id"),
            "started": e.get("startedAt"),
            "status": e.get("status"),
            "duration_s": fmt_dur(e.get("startedAt") or "", e.get("stoppedAt")),
        }
        for e in data
    ]


def cmd_active(host, key, args):
    params = {"limit": "100", "status": "running", "includeData": "false"}
    data = http_get(f"{host}/api/v1/executions?" + urllib.parse.urlencode(params), key).get("data", [])
    names = workflow_name_map(host, key)
    return [
        {"id": e.get("id"), "started": e.get("startedAt"), "workflow": names.get(e.get("workflowId"), e.get("workflowId"))}
        for e in data
    ]


def cmd_health(host, key, args):
    wfs = http_get(f"{host}/api/v1/workflows?limit=250", key).get("data", [])
    active = [w for w in wfs if w.get("active")]
    execs = http_get(f"{host}/api/v1/executions?limit=250&includeData=false", key).get("data", [])
    by_status = Counter((e.get("status") or "?").lower() for e in execs)
    return {
        "workflows_total": len(wfs),
        "workflows_active": len(active),
        "last_250_executions": dict(by_status),
        "first_exec_at": execs[-1].get("startedAt") if execs else None,
        "latest_exec_at": execs[0].get("startedAt") if execs else None,
    }


def cmd_search(host, key, args):
    wfs = http_get(f"{host}/api/v1/workflows?limit=250", key).get("data", [])
    q = args.query.lower()
    matched = [w for w in wfs if q in (w.get("name") or "").lower()]
    return [
        {"id": w["id"], "name": w["name"], "active": w.get("active"), "updatedAt": w.get("updatedAt")}
        for w in matched[:50]
    ]


def cmd_wf_info(host, key, args):
    wf = http_get(f"{host}/api/v1/workflows/{args.workflow_id}", key)
    triggers = []
    for n in wf.get("nodes", []):
        t = n.get("type", "")
        if "trigger" in t.lower() or "webhook" in t.lower() or "schedule" in t.lower():
            triggers.append({"name": n.get("name"), "type": t})
    return {
        "id": wf.get("id"),
        "name": wf.get("name"),
        "active": wf.get("active"),
        "node_count": len(wf.get("nodes", [])),
        "triggers": triggers,
        "updatedAt": wf.get("updatedAt"),
        "createdAt": wf.get("createdAt"),
    }


def main():
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="cmd", required=True)

    p = sub.add_parser("recent")
    p.add_argument("--days", type=int, default=7)
    p.add_argument("--status")
    p.add_argument("--limit", type=int, default=100)

    p = sub.add_parser("exec")
    p.add_argument("id")
    p.add_argument("--include-data", action="store_true")

    p = sub.add_parser("errors")
    p.add_argument("--days", type=int, default=7)
    p.add_argument("--limit", type=int, default=50)

    p = sub.add_parser("wf")
    p.add_argument("workflow_id")
    p.add_argument("--limit", type=int, default=50)

    sub.add_parser("active")
    sub.add_parser("health")

    p = sub.add_parser("search")
    p.add_argument("query")

    p = sub.add_parser("wf-info")
    p.add_argument("workflow_id")

    args = parser.parse_args()

    host, key = resolve_creds()

    handler = {
        "recent": cmd_recent, "exec": cmd_exec, "errors": cmd_errors,
        "wf": cmd_wf, "active": cmd_active, "health": cmd_health,
        "search": cmd_search, "wf-info": cmd_wf_info,
    }[args.cmd]
    out = handler(host, key, args)

    print(json.dumps({"host": host, "result": out}, indent=2, default=str))


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        sys.stderr.write(f"ERROR: {e}\n")
        sys.exit(1)

#!/usr/bin/env python3
"""
usage_insights.py — a friendly look at how you've been using Claude Code.

Reads your local Claude Code session transcripts (~/.claude/projects/**/*.jsonl)
and prints a plain summary: how many sessions, which tools you lean on, which
skills you've actually used, and how recently. Nothing leaves your machine.

Usage:
  usage_insights.py [--days N]     # default: last 30 days
"""
from __future__ import annotations

import argparse
import json
import os
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

PROJECTS = Path(os.path.expanduser("~/.claude/projects"))


def parse_ts(obj: dict) -> float | None:
    ts = obj.get("timestamp")
    if not ts:
        return None
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00")).timestamp()
    except (ValueError, AttributeError):
        return None


def iter_tool_uses(message: dict):
    """Yield (tool_name, input_dict) for each tool_use in an assistant message."""
    content = message.get("content")
    if not isinstance(content, list):
        return
    for block in content:
        if isinstance(block, dict) and block.get("type") == "tool_use":
            yield block.get("name", "?"), (block.get("input") or {})


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--days", type=int, default=30)
    args = ap.parse_args()

    if not PROJECTS.exists():
        print("No Claude Code history found yet (~/.claude/projects is empty).")
        print("Use Claude Code for a bit, then run this again.")
        return

    cutoff = datetime.now(timezone.utc).timestamp() - args.days * 86400
    files = list(PROJECTS.glob("**/*.jsonl"))

    sessions = 0
    user_msgs = 0
    tools = Counter()
    skills = Counter()
    last_active = 0.0

    for f in files:
        touched = False
        try:
            lines = f.read_text(errors="ignore").splitlines()
        except OSError:
            continue
        for line in lines:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                continue
            t = parse_ts(obj)
            if t is not None:
                if t < cutoff:
                    continue
                touched = True
                last_active = max(last_active, t)
            typ = obj.get("type")
            msg = obj.get("message") or {}
            if typ == "user":
                user_msgs += 1
            elif typ == "assistant":
                for name, inp in iter_tool_uses(msg):
                    tools[name] += 1
                    if name == "Skill":
                        skills[inp.get("skill") or inp.get("command") or "?"] += 1
        if touched:
            sessions += 1

    print(f"=== Claude Code usage — last {args.days} days ===\n")
    if sessions == 0:
        print("No activity in this window. Try a wider --days value.")
        return

    when = datetime.fromtimestamp(last_active, timezone.utc).strftime("%Y-%m-%d") if last_active else "?"
    print(f"Sessions:        {sessions}")
    print(f"Your messages:   {user_msgs}")
    print(f"Last active:     {when}\n")

    print("Tools you use most:")
    for name, n in tools.most_common(10):
        print(f"  {n:>5}  {name}")
    if not tools:
        print("  (none yet)")

    print("\nSkills you've actually used:")
    if skills:
        for name, n in skills.most_common(15):
            print(f"  {n:>5}  {name}")
    else:
        print("  (none yet — try: 'use the claude-code-tutorial skill')")

    print("\nTip: skills you've never used are worth a look — ask Claude what each one does.")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
clickup_search.py — direct ClickUp REST queries, MCP-free.

Single-user. Reads credentials from the environment:
  CLICKUP_API_TOKEN     (required) — personal API token, e.g. pk_12345_ABC...
  CLICKUP_WORKSPACE_ID  (optional) — team/workspace id, e.g. 90000000
                                     required for: search, recent, spaces,
                                     and `lists` without --space.

A `.env` file in the current directory (or repo root) is auto-loaded if present;
real environment variables take precedence over .env values.

Usage:
  clickup_search.py tasks <list_id> [--status <status>] [--limit N]
  clickup_search.py task <task_id>
  clickup_search.py search <query> [--limit N]
  clickup_search.py lists [--space <space_id>]
  clickup_search.py spaces
  clickup_search.py recent [--days N] [--limit N]   # tasks updated in last N days, workspace-wide
  clickup_search.py comment <task_id> <body>
  clickup_search.py update <task_id> --status <status>

Output: JSON to stdout. Errors → stderr, exit 1.
"""
from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.parse
import urllib.request
from pathlib import Path

API_BASE = "https://api.clickup.com/api/v2"


def load_dotenv() -> None:
    """Load KEY=VALUE pairs from a .env file (cwd, then parent dirs up to repo
    root) into os.environ without overriding existing real env vars.

    Looks for the nearest .env walking upward; stops at the filesystem root.
    """
    cwd = Path.cwd()
    for d in [cwd, *cwd.parents]:
        env_path = d / ".env"
        if not env_path.exists():
            continue
        try:
            for raw in env_path.read_text(errors="ignore").splitlines():
                line = raw.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, _, val = line.partition("=")
                key = key.strip()
                val = val.strip().strip('"').strip("'")
                if key and key not in os.environ:
                    os.environ[key] = val
        except OSError:
            pass
        break  # only load the nearest .env


def resolve_credentials() -> tuple[str, str | None]:
    """Return (token, workspace_id). Raises if no token is found."""
    token = os.environ.get("CLICKUP_API_TOKEN")
    ws = os.environ.get("CLICKUP_WORKSPACE_ID")
    if not token:
        raise RuntimeError(
            "No ClickUp token found. Set CLICKUP_API_TOKEN in your environment "
            "or in a .env file at your repo root. Get a token from "
            "ClickUp → Settings → Apps → API Token (format: pk_...)."
        )
    return token, ws


def http(method: str, path: str, token: str, params: dict | None = None, body: dict | None = None):
    url = API_BASE + path
    if params:
        url += "?" + urllib.parse.urlencode({k: v for k, v in params.items() if v is not None})
    data = json.dumps(body).encode() if body is not None else None
    headers = {"Authorization": token, "Content-Type": "application/json"}
    req = urllib.request.Request(url, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            raw = r.read().decode()
            return json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        err_body = e.read().decode(errors="ignore")
        raise RuntimeError(f"ClickUp HTTP {e.code}: {err_body[:300]}")


def cmd_tasks(token, args):
    params = {"include_closed": "true", "subtasks": "true"}
    if args.status:
        params["statuses[]"] = args.status
    res = http("GET", f"/list/{args.list_id}/task", token, params)
    tasks = res.get("tasks", [])[: args.limit]
    return [
        {
            "id": t["id"],
            "name": t["name"],
            "status": t.get("status", {}).get("status"),
            "url": t.get("url"),
            "due": t.get("due_date"),
            "assignees": [a.get("username") for a in t.get("assignees", [])],
        }
        for t in tasks
    ]


def cmd_task(token, args):
    res = http("GET", f"/task/{args.task_id}", token, {"include_subtasks": "true"})
    return {
        "id": res.get("id"),
        "name": res.get("name"),
        "status": res.get("status", {}).get("status"),
        "url": res.get("url"),
        "description": res.get("description") or res.get("text_content"),
        "list": res.get("list", {}).get("name"),
        "assignees": [a.get("username") for a in res.get("assignees", [])],
        "tags": [t.get("name") for t in res.get("tags", [])],
        "custom_fields": [
            {"name": f.get("name"), "value": f.get("value")}
            for f in res.get("custom_fields", [])
            if f.get("value") is not None
        ],
    }


def cmd_search(token, ws, args):
    if not ws:
        raise RuntimeError("CLICKUP_WORKSPACE_ID not set — required for search.")
    res = http(
        "GET",
        f"/team/{ws}/task",
        token,
        {"include_closed": "true", "page": "0", "subtasks": "true"},
    )
    q = args.query.lower()
    tasks = res.get("tasks", [])
    matched = [
        t
        for t in tasks
        if q in (t.get("name") or "").lower() or q in (t.get("text_content") or "").lower()
    ]
    return [
        {"id": t["id"], "name": t["name"], "status": t.get("status", {}).get("status"), "url": t.get("url")}
        for t in matched[: args.limit]
    ]


def cmd_lists(token, ws, args):
    if args.space:
        res = http("GET", f"/space/{args.space}/list", token)
        return [{"id": l["id"], "name": l["name"]} for l in res.get("lists", [])]
    if not ws:
        raise RuntimeError("CLICKUP_WORKSPACE_ID required (or pass --space).")
    spaces = http("GET", f"/team/{ws}/space", token).get("spaces", [])
    out = []
    for s in spaces:
        lists = http("GET", f"/space/{s['id']}/list", token).get("lists", [])
        for l in lists:
            out.append({"space": s["name"], "id": l["id"], "name": l["name"]})
    return out


def cmd_spaces(token, ws):
    if not ws:
        raise RuntimeError("CLICKUP_WORKSPACE_ID required.")
    res = http("GET", f"/team/{ws}/space", token)
    return [{"id": s["id"], "name": s["name"]} for s in res.get("spaces", [])]


def cmd_recent(token, ws, args):
    if not ws:
        raise RuntimeError("CLICKUP_WORKSPACE_ID required.")
    import time

    since_ms = int((time.time() - args.days * 86400) * 1000)
    res = http(
        "GET",
        f"/team/{ws}/task",
        token,
        {
            "date_updated_gt": str(since_ms),
            "include_closed": "true",
            "subtasks": "true",
            "order_by": "updated",
            "reverse": "true",
        },
    )
    return [
        {
            "id": t["id"],
            "name": t["name"],
            "status": t.get("status", {}).get("status"),
            "list": t.get("list", {}).get("name"),
            "updated": t.get("date_updated"),
        }
        for t in res.get("tasks", [])[: args.limit]
    ]


def cmd_comment(token, args):
    res = http("POST", f"/task/{args.task_id}/comment", token, body={"comment_text": args.body})
    return {"id": res.get("id"), "ok": True}


def cmd_update(token, args):
    body = {}
    if args.status:
        body["status"] = args.status
    res = http("PUT", f"/task/{args.task_id}", token, body=body)
    return {"id": res.get("id"), "status": res.get("status", {}).get("status")}


def main():
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="cmd", required=True)

    p_tasks = sub.add_parser("tasks")
    p_tasks.add_argument("list_id")
    p_tasks.add_argument("--status")
    p_tasks.add_argument("--limit", type=int, default=50)

    p_task = sub.add_parser("task")
    p_task.add_argument("task_id")

    p_search = sub.add_parser("search")
    p_search.add_argument("query")
    p_search.add_argument("--limit", type=int, default=20)

    p_lists = sub.add_parser("lists")
    p_lists.add_argument("--space")

    sub.add_parser("spaces")

    p_recent = sub.add_parser("recent")
    p_recent.add_argument("--days", type=int, default=7)
    p_recent.add_argument("--limit", type=int, default=50)

    p_comment = sub.add_parser("comment")
    p_comment.add_argument("task_id")
    p_comment.add_argument("body")

    p_update = sub.add_parser("update")
    p_update.add_argument("task_id")
    p_update.add_argument("--status")

    args = parser.parse_args()

    load_dotenv()
    token, ws = resolve_credentials()

    if args.cmd == "tasks":
        out = cmd_tasks(token, args)
    elif args.cmd == "task":
        out = cmd_task(token, args)
    elif args.cmd == "search":
        out = cmd_search(token, ws, args)
    elif args.cmd == "lists":
        out = cmd_lists(token, ws, args)
    elif args.cmd == "spaces":
        out = cmd_spaces(token, ws)
    elif args.cmd == "recent":
        out = cmd_recent(token, ws, args)
    elif args.cmd == "comment":
        out = cmd_comment(token, args)
    elif args.cmd == "update":
        out = cmd_update(token, args)
    else:
        parser.error("unknown command")

    print(json.dumps({"result": out}, indent=2, default=str))


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        sys.stderr.write(f"ERROR: {e}\n")
        sys.exit(1)

#!/usr/bin/env node
// Mode 1: Inspect — multi-viewport screenshots, console errors, network failures, optional DOM probes.
// Invocation: node inspect.js (reads PW_INSPECT_CONFIG env var as JSON)
// Config shape: { url, viewports?: number[], probes?: {[selector]: ('style'|'rect'|'text')[]}, headed?: boolean, waitFor?: string }

const path = require('path');
const fs = require('fs');

// Resolve Playwright from this skill's local install (templates/ -> skill root -> node_modules),
// falling back to a normal require so a globally/locally installed playwright also works.
function loadPlaywright() {
  const skillRoot = path.resolve(__dirname, '..');
  const local = path.join(skillRoot, 'node_modules', 'playwright');
  try { return require(local); } catch (_) {}
  return require('playwright'); // resolves from node_modules on the normal search path
}
const { chromium } = loadPlaywright();

// Per-run output dir. Override with PW_OUT_DIR; defaults to the OS temp dir.
const OUT_BASE = process.env.PW_OUT_DIR || path.join(require('os').tmpdir(), 'pw-out');

(async () => {
  const cfg = JSON.parse(process.env.PW_INSPECT_CONFIG || '{}');
  const url = cfg.url;
  if (!url) { console.log(JSON.stringify({ ok: false, error: 'missing url in PW_INSPECT_CONFIG' })); process.exit(1); }

  const viewports = cfg.viewports || [375, 768, 1440];
  const probes = cfg.probes || {};
  const headed = !!cfg.headed;
  const waitFor = cfg.waitFor;

  const ts = new Date().toISOString().replace(/[:.]/g, '-');
  const outDir = path.join(OUT_BASE, ts);
  fs.mkdirSync(outDir, { recursive: true });

  const result = {
    ok: true, url, out_dir: outDir,
    screenshots: [], console_errors: [], network_failures: [], probes: {}
  };

  const browser = await chromium.launch({ headless: !headed });
  try {
    for (const width of viewports) {
      const ctx = await browser.newContext({ viewport: { width, height: Math.round(width * 1.6) } });
      const page = await ctx.newPage();

      page.on('console', msg => {
        if (msg.type() === 'error' || msg.type() === 'warning') {
          result.console_errors.push({ viewport: width, type: msg.type(), text: msg.text(), location: msg.location() });
        }
      });
      page.on('pageerror', err => {
        result.console_errors.push({ viewport: width, type: 'pageerror', text: err.message });
      });
      page.on('requestfailed', req => {
        result.network_failures.push({ viewport: width, url: req.url(), failure: req.failure()?.errorText });
      });
      page.on('response', resp => {
        if (resp.status() >= 400) {
          result.network_failures.push({ viewport: width, url: resp.url(), status: resp.status() });
        }
      });

      await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });
      if (waitFor) await page.waitForSelector(waitFor, { timeout: 10000 });

      const shotPath = path.join(outDir, `${width}.png`);
      await page.screenshot({ path: shotPath, fullPage: true });
      result.screenshots.push(shotPath);

      // Probes only on the first (smallest) viewport to keep output small
      if (width === viewports[0]) {
        for (const [selector, fields] of Object.entries(probes)) {
          try {
            const probe = await page.$eval(selector, (el, fields) => {
              const out = {};
              if (fields.includes('style')) {
                const cs = window.getComputedStyle(el);
                out.style = { color: cs.color, background: cs.backgroundColor, font: cs.font, display: cs.display };
              }
              if (fields.includes('rect')) {
                const r = el.getBoundingClientRect();
                out.rect = { x: r.x, y: r.y, w: r.width, h: r.height };
              }
              if (fields.includes('text')) out.text = el.textContent?.slice(0, 200);
              return out;
            }, fields);
            result.probes[selector] = probe;
          } catch (e) {
            result.probes[selector] = { error: e.message };
          }
        }
      }

      await ctx.close();
    }
  } catch (e) {
    result.ok = false;
    result.error = e.message;
    try {
      const errShot = path.join(outDir, 'error.png');
      const ctx = await browser.newContext();
      const page = await ctx.newPage();
      await page.goto(url).catch(() => {});
      await page.screenshot({ path: errShot }).catch(() => {});
      result.error_screenshot = errShot;
    } catch (_) {}
  } finally {
    await browser.close();
  }

  console.log(JSON.stringify(result));
})();

